    explanation: '実技試験で用いる高層天気図の気圧面は、それぞれ異なる気象学的役割を担うために選ばれている。850hPa（高度約1500m）は地表摩擦の影響が小さくなり始める下層大気の代表面で、気温分布から前線帯・寒気/暖気移流を判断する。700hPa（約3000m）は中層の湿数分布から雲・降水域を推定するのに適する。500hPa（約5500m）は対流圏中層の代表面であり、渦度の非発散に近い高度としてトラフ・リッジや渦度移流の診断に使われる。300hPa（約9000m）は圏界面付近でジェット気流・上層発散の解析に用いられる。\n\n【図解】\n★重要：850hPa＝下層気温・前線、700hPa＝湿数・鉛直流、500hPa＝渦度・トラフリッジ、300hPa＝ジェット気流、と役割分担がある\n○補足：500hPaは大気の平均的な非発散高度に近く、渦度の保存則を用いた診断に適する\n×誤りやすい点：どれか一つの気圧面だけで総観場を判断しようとすると、必要な情報（下層の前線と上層のジェットなど）を見落とす\n→結論：気圧面ごとの役割を理解し、複数面を組み合わせて立体的に大気を解析する',
