    correctKey: 'A',
    explanation: 'ジェットストリーク（ジェット気流上の風速極大部）付近では、地衡風からのずれ（非地衡風成分）による循環が生じ、入口（風上側、風速が加速する側）の右側と出口（風下側、風速が減速する側）の左側で上層発散が卓越する「4象限モデル」が知られている。この上層発散域の下方では下層の収束・上昇流が強制され、地上低気圧の発達に有利な条件となる。実技試験では300hPa天気図の風速極大部（ジェットストリーク）の位置と地上低気圧の位置関係を確認する設問が出される。\n\n【図解】\n★重要：ジェットストリーク入口右側・出口左側＝上層発散＝地上低気圧発達に有利\n○補足：入口左側・出口右側は上層収束域で、地上では高気圧性・下降流が卓越しやすい\n×誤りやすい点：ジェット軸直下を一律に上昇流域と考えるのは誤りで、入口・出口・左右で性質が異なる\n→結論：ジェットストリークの位置と4象限モデルを地上低気圧の位置に重ね合わせ、発達の可能性を評価する',
