    correctKey: 'A',
    explanation: '陸地は海面に比べて熱容量が小さく、日射を受けると速く暖まり、夜間は速く冷える性質を持つ。日中は陸上の気温が海上より高くなり、陸上で上昇気流が生じて地表付近の気圧がわずかに下がるため、海から陸へ向かう「海風」が吹く。夜間はこの関係が逆転し、陸上の方が速く冷えて気圧がわずかに高くなるため、陸から海へ向かう「陸風」が吹く。この日変化は総観規模の風が弱い晴天日に最も明瞭に現れ、朝夕の風の入れ替わりの瞬間には「凪（なぎ）」と呼ばれる無風状態が生じることもある。\n\n【図解】\n★重要：日中＝海風（海→陸）、夜間＝陸風（陸→海）。陸地の熱容量の小ささが原動力\n○補足：朝夕の風向転換時には一時的に無風となる「凪」が観測されることがある\n×誤りやすい点：海風・陸風の吹く時間帯（日中・夜間）を逆に覚えないよう注意する\n→結論：晴天弱風日の局地天気予報では、海陸風の日変化パターンを踏まえて風向・天気の変化を予想する',
