    correctKey: 'A',
    explanation: '盆地地形では、晴れて風の弱い夜間、周囲の斜面が放射冷却によって冷やされ、その冷えた重い空気が山風として盆地の底へ向かって流れ下る。盆地は周囲を山に囲まれ空気が滞留しやすい地形であるため、この冷気が底部にたまって層状の「冷気湖」を形成し、さらに放射冷却が進むことで、周辺の平地よりも著しい低温（内陸盆地特有の厳しい冷え込み）が朝方に観測されることがある。日本の内陸盆地（例えば長野盆地・甲府盆地など）で記録的な低温が観測されやすいのはこの効果による。実技試験では地形・風速・雲量から冷気湖形成の可能性を評価する設問が出される。\n\n【図解】\n★重要：盆地の冷気湖＝夜間の放射冷却＋周囲斜面からの冷気流入（山風）が底部に滞留する現象\n○補足：晴天・弱風（放射冷却が進みやすい条件）の夜ほど冷気湖が顕著になり、朝の低温が際立つ\n×誤りやすい点：盆地の低温を単純な「標高効果」とだけ捉えず、冷気の滞留（盆地特有の地形効果）を考慮する\n→結論：盆地地形・晴天弱風の夜間条件がそろった場合、周辺の平地より一段と厳しい低温を予想する',
