    correctKey: 'A',
    explanation: '空気塊が上昇・下降する際、水蒸気の凝結（または蒸発）を伴わない場合の気温変化を表す「乾燥断熱線」は、およそ100mにつき約1℃の割合（乾燥断熱減率）で傾く。一方、空気塊が飽和して水蒸気が凝結しながら上昇する場合は、凝結に伴う潜熱の放出により冷却が緩やかになるため、「湿潤断熱線」の傾き（湿潤断熱減率）は乾燥断熱線よりも緩やかになる（高温になるほど潜熱の効果が大きく、より緩やかになる）。この2つの線の傾きの違いを理解することが、エマグラムを用いた安定度診断の基礎となる。\n\n【図解】\n★重要：乾燥断熱線（約1℃/100m）＞湿潤断熱線（潜熱放出で緩やか、高温ほどさらに緩やか）\n○補足：未飽和の空気塊は乾燥断熱線に沿って、飽和した空気塊は湿潤断熱線に沿って状態変化する\n×誤りやすい点：2つの線の傾きの大小関係を逆に覚えない（乾燥断熱線の方が急）\n→結論：気塊の状態（未飽和か飽和か）に応じて適切な断熱線をたどり、上昇時の気温変化を正しく評価する',
