    explanation: 'ショワルターの安定指数（SSI）は、850hPa面の空気塊を仮に断熱的に（未飽和なら乾燥断熱線、飽和状態に達した後は湿潤断熱線に沿って）500hPa面まで持ち上げたときに得られる気温（持ち上げ後の気温）と、実際に観測された500hPa面の環境気温との差（実況気温－持ち上げ後の気温）で定義される。この値が負に大きいほど、持ち上げられた空気塊が周囲より暖かい（浮力を持つ）ことを意味し、大気は不安定であると判断される。SSIはエマグラム上で850hPaの状態点から断熱線をたどり、500hPaの環境気温曲線との差を読み取ることで実技的に算出できる。\n\n【図解】\n★重要：SSI＝（500hPa環境気温）－（850hPaを断熱的に持ち上げた気温）。負に大きいほど不安定\n○補足：SSIが+3以上で安定、0未満で不安定、-3未満で著しく不安定、といった目安が実技的に用いられる\n×誤りやすい点：SSIを単純な気温差（850hPaと500hPaの環境気温差）と混同しない。断熱的な持ち上げ過程を経た値との比較である\n→結論：エマグラム上で850hPaから断熱線をたどり、500hPa環境気温との差からSSIを読み取る手順を身につける',
