    explanation: '大きな河川（指定河川）の洪水による災害を防止するため、気象庁と河川管理者（国土交通省の地方整備局や都道府県）が共同で「指定河川洪水予報」を発表する体制がとられている。この予報は、降水の予測情報（気象庁が担当）と、実際の河川の水位・流量観測データやダムの放流状況（河川管理者が担当）を統合し、対象河川の氾濫の危険性を予測するものである。大雨警報・注意報のように気象庁単独で発表する情報とは異なり、気象と河川管理という2つの専門分野が連携して発表する点が特徴であり、実技試験でもこの発表体制の違いが問われることがある。\n\n【図解】\n★重要：指定河川洪水予報＝気象庁（降水予測）＋河川管理者（水位・流量観測）の共同発表\n○補足：予報は「氾濫注意情報」「氾濫警戒情報」「氾濫危険情報」「氾濫発生情報」などの段階で発表される\n×誤りやすい点：気象庁単独の警報・注意報と、河川管理者との共同発表である指定河川洪水予報を混同しない\n→結論：大河川の氾濫リスクを評価する際は、気象庁の大雨情報だけでなく、指定河川洪水予報（水位情報）も併せて確認する',
