    correctKey: 'A',
    explanation: '雷監視システム（LIDEN: Lightning Detection Network）は、落雷（雲放電・対地放電）が発生した際に生じる電磁波を複数地点のセンサーで受信し、その位置と時刻をリアルタイムで検出するシステムである。積乱雲内部では、氷晶やあられなどの氷粒子同士の衝突によって電荷が分離・蓄積され、これが放電（雷）として解放される。単位時間・単位面積あたりの落雷数（発雷密度）が急激に増加する状況は、積乱雲内部の対流活動が活発化し、氷粒子の生成・衝突が盛んになっていることを示唆するため、レーダーエコーの反射強度やエコー頂高度の変化と組み合わせることで、積乱雲の急速な発達や危険度をより多角的に評価する実況監視の材料として活用される。\n\n【図解】\n★重要：発雷密度の急増＝積乱雲内部の対流活発化（氷粒子の生成・電荷分離の活発化）を示唆する指標\n○補足：雷監視システムはリアルタイムの実況監視に活用され、レーダー・衛星情報と組み合わせて総合判断される\n×誤りやすい点：落雷を単なる偶発的な現象と捉えず、積乱雲の発達段階を反映する物理的な指標として活用する\n→結論：発雷密度の時間変化をレーダーエコーの変化と併せて監視し、積乱雲の急発達・危険度を総合的に評価する',
    difficulty: 'standard',
    examYear: '令和4年',
