    explanation: 'METAR（定時飛行場実況気象通報）は、世界中の飛行場で定時（通常1時間ごと、必要に応じて随時）に観測される風向風速・視程・現在天気・雲量雲高・気温・露点温度・気圧などを定型のフォーマットで報じる実況観測報である。一方、TAF（飛行場予報）は、その飛行場における今後一定期間（多くの場合24〜30時間程度）の気象状態（風・視程・雲・降水等の予測）を、これも定型のフォーマットで発表する予報である。パイロットや航空管制官は、METARで現在の状況を、TAFで今後の見通しを把握し、離着陸の可否判断や飛行計画の立案に活用する。実技試験では、この「実況（METAR）」と「予報（TAF）」という基本的な役割の違いを正確に理解しておく必要がある。\n\n【図解】\n★重要：METAR＝定時実況観測報、TAF＝飛行場予報（将来予測）。役割が明確に異なる\n○補足：両者とも国際的に統一された定型フォーマット（略号）で記述され、世界中で共通に運用されている\n×誤りやすい点：METARとTAFの「実況か予報か」という役割を逆に覚えない\n→結論：現在の状況把握にはMETAR、今後の飛行計画の判断にはTAFを用いるという使い分けを理解する',
