    correctKey: 'A',
    explanation: '航空機の運航方式には、パイロットが自身の目視によって地上や周辺の障害物・他機を確認しながら飛行する「有視界飛行方式（VFR）」と、計器の指示および航空管制からの指示に基づいて飛行する「計器飛行方式（IFR）」がある。霧・低い雲・激しい降水などにより視程や雲底高度が一定の基準（気象状態基準、いわゆるミニマム）を下回ると、目視に頼るVFRでは周辺の状況を十分に把握できず安全な運航が困難になるため、計器のみを頼りに、航空管制の管理下で飛行するIFRへの切り替え（あるいは当初からのIFR計画）が必要になる。実技試験では、METAR・TAFの視程・雲底高度の情報から、その空港の運航がVFR可能な状況かIFRが必要な状況かを判断する視点が問われることがある。\n\n【図解】\n★重要：視程・雲底高度が基準を下回る＝VFR困難＝IFRによる計器・管制頼みの運航が必要\n○補足：各空港・滑走路には、着陸の可否を左右する視程・雲底高度の最低基準（気象条件基準）が定められている\n×誤りやすい点：VFR・IFRを単なる「方式の名前」とせず、視程条件によって切り替えが必要になる実質的な意味を理解する\n→結論：METAR・TAFの視程・雲底高度情報から、VFR可能かIFRが必要な状況かを実技的に判断する',
    difficulty: 'standard',
    examYear: '令和4年',
