    correctKey: 'A',
    explanation: '光化学オキシダント（光化学スモッグの原因物質）は、工場・自動車等から排出された窒素酸化物や揮発性有機化合物（VOC）が、大気中で強い日射（特に紫外線）のエネルギーを受けて光化学反応を起こすことで二次的に生成される大気汚染物質である。このため、光化学オキシダントの濃度は、日射が強い夏の晴天日に高くなりやすい。さらに、風が弱く大気が滞留しやすい気象条件（移動性高気圧に覆われた穏やかな天気等）が重なると、生成された光化学オキシダントが拡散されずに蓄積し、高濃度化しやすくなる。気象台や地方自治体は、こうした気象条件（強い日射・弱風の予想）を踏まえて光化学スモッグ予報・注意報の発表判断を行っている。\n\n【図解】\n★重要：光化学オキシダント＝強い日射（紫外線）による光化学反応で生成。夏の晴天日に濃度が高まりやすい\n○補足：風が弱く汚染物質が滞留しやすい気象条件が重なると、さらに高濃度化しやすい\n×誤りやすい点：光化学スモッグを単なる大気汚染と捉えず、日射（紫外線）が本質的な生成要因であることを理解する\n→結論：夏の強い日射・弱風の予想が重なる日は、光化学スモッグの発生・高濃度化リスクを評価して注意喚起する',
    difficulty: 'advanced',
    examYear: '令和4年',
