    correctKey: 'A',
    explanation: '実技試験で複数の資料の間に食い違いが見られる場合、まず直近の実況観測データ（アメダス、地上天気図、衛星・レーダー画像等）は「今まさに起きている事実」を反映した最も確実な情報として最優先で重視すべきである。その上で、数値予報資料については、初期時刻からの予測時間が短いものほど、大気のカオス性に起因する誤差の蓄積が少なく、相対的に信頼度が高いと考えられる。逆に予測時間が長くなるほど不確実性が増すため、その予測値を鵜呑みにせず、幅を持った解釈をすることが求められる。実技試験では、このような資料間の優先順位・信頼度の違いを踏まえた総合的な判断力が問われる。\n\n【図解】\n★重要：優先順位の目安＝直近の実況観測 ＞ 予測時間の短い数値予報 ＞ 予測時間の長い数値予報\n○補足：実況と予測が食い違う場合、実況を基準にモデルのバイアス（系統誤差）の可能性も考慮する\n×誤りやすい点：先の時刻の予測値を実況と同じ確度で扱ってしまわないよう注意する\n→結論：資料の性質（実況か予測か、予測時間の長さ）に応じた優先順位を踏まえて総合的に解釈する',
    difficulty: 'standard',
    examYear: '令和4年',
